sys_script_include.script:
var CheckEnrollment = Class.create();
CheckEnrollment.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    isAlreadyEnrolled: function() {
        var openedBy = this.getParameter('sysparm_opened_by');
        var dateId = this.getParameter('sysparm_date_id');

        gs.info(' CheckEnrollment → opened_by=' + openedBy + ', date=' + dateId);

        var gr = new GlideRecord('x_752538_course_enrollment');
        gr.addQuery('opened_by', openedBy);
        gr.addQuery('date', dateId);
        gr.query();

        var found = gr.hasNext();
        gs.info(' CheckEnrollment → already enrollment? ' + found);

        return found ? 'true' : 'false';
    },

    type: 'CheckEnrollment'
});
